from __future__ import annotations
import json
import logging
import os
import string
import time
from pathlib import Path
from typing import Union

from taf.transport.ssh.connection import SSHConnection, connect

from .controller import Controller
from .exception import (
    ConnectionAlreadySetUpError,
    ConnectionNotSetUpError,
    FileCollectorError,
    InvalidDestinationError,
)
from .operator import LogOperator
from .util import retry, sh_quote


class SyslogInstance:
    """
    Class representing a given syslog instance. It allows to interact with syslog service, and enables operations like
    starting, stopping, collecting logs, counting messages, etc.

    :param log_dir: Directory in which log files should be stored
    :type log_dir: str
    :param log_name: Log file name
    :type log_name: str
    :param host_ip: IP address of the host where syslog service will be running
    :type host_ip: str
    :param ip:  Custom IP address service should listen for. defaults to "" which means all interfaces
    :type ip: str, optional
    :param ports: , defaults to (51000, 51001, 51003, 50011)
    :type ports: Union[tuple[int], int], optional
    :param file_limit: Max size of log file in bytes. Defaults to 0 which means unlimited size
    :type file_limit: int, optional
    :param add_line_number: Flag indicating if log entries should be prepended with line number, defaults to False
    :type add_line_number: bool, optional
    :param virtualenv_dir: Custom virtualenv directory to be used, defaults to None
    :type virtualenv_dir: str, optional
    :param cli_prefix: Prefix which will allow wrapping cli_syslog with another command or pass environment variables, defaults to None
    :type cli_prefix: str, optional
    :param temp_dir: Allows to override the default /tmp
    :param temp_dir: str, optional
    """

    def __init__(
        self,
        log_dir: str,
        log_name: str,
        host_ip: str,
        ip: str = "",
        ports: Union[tuple[int], int] = (51000, 51001, 51003, 50011),
        file_limit: int = 0,
        add_line_number: bool = False,
        virtualenv_dir: str | None = None,
        cli_prefix: str | None = None,
        temp_dir: str = "/tmp",
    ):
        _disallow_special_characters(log_dir)
        _disallow_special_characters(log_name)
        self._logger = logging.getLogger()
        self._connection = None

        self.temp_dir = Path(temp_dir)
        self.temp_dir.mkdir(parents=True, exist_ok=True)
        self._ctrl = Controller(
            log_dir=log_dir,
            log_name=log_name,
            ip=ip,
            ports=self._convert_to_list_of_ports(ports),
            file_limit=file_limit,
            add_line_number=add_line_number,
            cli_prefix=cli_prefix,
            virtualenv_dir=self._get_virtualenv_dir(virtualenv_dir, host_ip),
            temp_dir=self.temp_dir,
        )
        self._operator = LogOperator(log_pattern=self._ctrl.log_pattern)
        self._file_limit = int(file_limit)
        self._savepoints = {}

    def setup(self, ssh_params: dict) -> None:
        """Create SSH connection and pass it to underlying objects

        :param ssh_params: Dictionary containing parameters of SSH connection: ssh_ip, ssh_username, ssh_password, ssh_port
        :type ssh_params: dict
        :raises ConnectionAlreadySetUp: If connection is already set up
        """
        if self._connection is None:
            self._connection = self._connect(**ssh_params)
            self._operator.connect(self._connection)
            self._ctrl.connect(self._connection)
        else:
            raise ConnectionAlreadySetUpError("This syslog instance is already connected!")

    def start(self) -> None:
        """Start syslog collection

        :raises ConnectionNotSetUp: Connection is not set up before trying to start syslog collection
        """
        if self._connection is None:
            raise ConnectionNotSetUpError(
                """SSH connection is not set up!
                Please setup the connection with SyslogInstance.setup() method first!"""
            )
        self._ctrl.start()

    @staticmethod
    @retry(attempts=3)
    def _connect(
        ssh_ip: str, ssh_username: str, ssh_password: str, ssh_port: int
    ) -> SSHConnection:
        return connect(ssh_ip, ssh_username, ssh_password, ssh_port)

    @staticmethod
    def _convert_to_list_of_ports(ports: Union[int, list[str], str]) -> list[int]:
        if isinstance(ports, (int, str)):
            return [int(ports)]
        else:
            return [int(port) for port in ports]

    def _get_virtualenv_dir(self, virtualenv_dir: str, host_ip: str) -> str:
        # Ensure local virtualenv is used when connecting to localhost
        #
        # XXX: In theory, this check should include sys.prefix !=
        # sys.base_prefix instead of checking os.environ['VIRTUAL_ENV'].
        #
        # In practice... we don't care. This edge case is sharp only if the
        # user manages to run interpreter from outside the active
        # virtualenv.
        if virtualenv_dir is not None:
            # User specified custom virtualenv directory
            return virtualenv_dir
        else:
            if "ENABLE-PROFILER" in self._get_cm_tags():
                # we are on UTE test line
                virtualenv_dir = "/home/ute/test_repo"
            if self._host_is_local(host_ip) and "VIRTUAL_ENV" in os.environ:
                # we are on localhost and want to use current virtualenv
                virtualenv_dir = os.environ["VIRTUAL_ENV"]
            return virtualenv_dir

    @staticmethod
    def _get_cm_tags() -> list[str]:
        return json.loads(os.getenv("CM_TAGS", default="[]"))

    @staticmethod
    def _host_is_local(hostname: str) -> bool:
        return hostname.startswith("127.")

    def collect_syslog_results(self, destination: str, unzip: bool) -> None:
        _disallow_special_characters(destination)
        destination = self._prepare_destination_path(destination, unzip)
        self._create_destination_directory(destination)
        self.stop_syslog()
        self._collect_results(destination, unzip, destination_is_dir=True)
        self.cleanup()

    @staticmethod
    def _create_destination_directory(destination: str) -> None:
        destination = Path(destination)
        destination_directory = (
            destination.parent
            if str(destination).endswith(".tar.gz")
            else destination
        )
        Path(destination_directory).mkdir(exist_ok=True, parents=True)

    def _prepare_destination_path(self, destination: str, unzip: bool) -> str:
        self._validate_destination(destination, unzip)
        if not destination:
            destination_path = (
                os.path.dirname(self._ctrl.log_pattern)
                if unzip
                else f"{self._ctrl.log_pattern}.tar.gz"
            )
        elif os.path.dirname(destination) == "":
            destination_path = os.path.join(os.getcwd(), destination)
        else:
            destination_path = destination
        return destination_path

    def _validate_destination(self, destination: str, unzip: bool) -> None:
        if not destination:
            return
        if unzip and destination.endswith(".tar.gz"):
            raise InvalidDestinationError(
                "unzip has to be False if destination is a tar.gz file"
            )
        elif unzip is False and not destination.endswith(".tar.gz"):
            raise InvalidDestinationError("Tar extension is not .tar.gz")

    def stop_syslog_and_cleanup(self) -> None:
        self.stop_syslog()
        self.cleanup()

    def stop_syslog(self) -> None:
        self._ctrl.stop()

    def cleanup(self):
        self._delete_syslog_tmp()
        self._ctrl.connection.disconnect()

    def _delete_syslog_tmp(self) -> None:
        tmp_files_pattern = self.temp_dir / "syslog_tmp*"
        cmd = f"rm -f {tmp_files_pattern}"
        savepoint_files = self._savepoints.values()
        if savepoint_files:
            files = [
                f"{self.temp_dir / Path(file).name}" for file in savepoint_files
            ]
            cmd = f"{cmd} {' '.join(files)}"
        self._ctrl.connection.execute(cmd)

    def count_syslog_messages(self, regexp: str) -> int:
        return self._operator.count_messages(regexp)

    def message_should_exist(self, regexp: str) -> str:
        return self._operator.message_exists(regexp)

    def message_should_exist_from_savepoint(self, regexp: str, savepoint: str) -> str:
        return self._operator.message_exists_from_savepoint(regexp, savepoint)

    def wait_for_message(self, regexp: str, timeout: int) -> str:
        return self._operator.wait_for_message(regexp, timeout)

    def capture_savepoint(self) -> str:
        log_path = self._ctrl.log_pattern
        if self._file_limit != 0:
            log_path = self._merge_logs(log_path)
        savepoint = self._operator.get_timestamp_of_last_line(log_path)
        return savepoint

    def collect_from_savepoint(
        self,
        savepoint: str,
        destination_file: str,
        file_limit: int = 0,
        compress: bool = False,
    ) -> None:
        destination_file = destination_file.replace(".tar.gz", "")
        destination = f"{destination_file}.tar.gz" if compress else destination_file

        self._verify_file_limit(file_limit)
        self._savepoints.update({savepoint: destination_file})

        self._create_remote_destination_directory(destination_file)
        self._merge_files_and_split_at_timestamp(
            timestamp=savepoint, destination_file=destination_file
        )

        if file_limit:
            self._split_savepoint_file(file_limit, destination_file)

        self._collect_results(
            destination, unzip=(not compress), file_pattern=f"{destination_file}*", destination_is_dir=False,
        )

    def _create_remote_destination_directory(self, destination_file: str) -> None:
        cmd = f"mkdir -p {sh_quote(Path(destination_file).parent.as_posix())}"
        self._logger.debug(f"Executing: {cmd}")
        self._ctrl.connection.execute(cmd)

    @staticmethod
    def _verify_file_limit(file_limit) -> None:
        file_limit = int(file_limit)
        if not (file_limit == 0 or file_limit >= 1000):
            raise ValueError(
                "file_limit must be at least 1000 bytes, or set to 0 (default)"
            )

    def _merge_files_and_split_at_timestamp(
        self, timestamp: str, destination_file: str
    ) -> None:
        log_path = self._ctrl.log_path
        if self._file_limit != 0:
            log_path = self._merge_logs(log_path)
        cmd = f"sed -n -e '/{timestamp}/,$p' {sh_quote(log_path)} > {sh_quote(destination_file)}"
        self._logger.debug(f"Executing: {cmd}")
        self._ctrl.connection.execute(cmd)

    def _split_savepoint_file(self, file_limit: int, destination_file: str) -> None:
        destination_file = sh_quote(destination_file)
        split_cmd = f"split -d -C {file_limit} {destination_file} {destination_file}_"
        self._logger.debug(f"Executing: {split_cmd}")
        self._ctrl.connection.execute(split_cmd)
        self._logger.debug(f"Executing: rm {destination_file}")
        self._ctrl.connection.execute(f"rm {destination_file}")

    def _merge_logs(self, log_path: str) -> str:
        file_name_or_pattern = Path(log_path).stem
        file_pattern = f"{file_name_or_pattern}*" if not file_name_or_pattern.endswith("*") else file_name_or_pattern
        full_path_pattern = sh_quote(Path(log_path).parent / file_pattern)
        merge_file_path = (self.temp_dir / f"syslog_tmp_{time.time_ns()}").as_posix()
        cmd = f"ls -v1 {full_path_pattern} | xargs cat > {merge_file_path}"
        self._logger.debug(f"Executing: {cmd}")
        self._ctrl.connection.execute(cmd)
        return merge_file_path

    def _collect_results(self, destination: str, unzip: bool, destination_is_dir=True, **kwargs) -> None:
        files_pattern = kwargs.get("file_pattern") or self._ctrl.log_pattern
        destination = Path(destination).absolute()
        try:
            self._ctrl.file_collector.get_files(
                files_pattern=files_pattern,
                destination=destination,
                destination_is_dir=destination_is_dir,
                unzip=unzip
            )
        except Exception as e:
            raise FileCollectorError(f"Error while collecting files: \n {e}")


def _disallow_special_characters(s: str | None) -> None:
    if not s:
        return
    allowed_characters = set(
        string.ascii_letters
        + string.digits
        + " ._-[]/@"
    )
    disallowed_characters = set(s).difference(allowed_characters)
    if disallowed_characters:
        raise ValueError(f"'{s}' contains disallowed character(s) {''.join(disallowed_characters)}")
